# student_processor.py - Refactored version

"""Process student grades and generate a summary report."""

data = [
    {"student_name": "Alice", "scores": [85, 90, 92], "grade": "A"},
    {"student_name": "Bob", "scores": [55, 60, 58], "grade": "F"},
    {"student_name": "Charlie", "scores": [78, 82, 80], "grade": "B"},
    {"student_name": "Diana", "scores": [95, 98, 96], "grade": "A"},
    {"student_name": "Eve", "scores": [40, 45, 42], "grade": "F"}
]


def calculate_average(scores):
    """Calculate the average of a list of scores."""
    if not scores:
        return 0.0

    total = sum(scores)
    return total / len(scores)


def get_status(average):
    """Determine pass/fail status based on average grade."""
    return "Pass" if average >= 60 else "Fail"


def process_students(students):
    """Process student data and calculate grades."""
    results = []

    for student in students:
        avg = calculate_average(student["scores"])
        status = get_status(avg)

        results.append({
            "name": student["student_name"],
            "average": round(avg, 2),
            "status": status
        })

    return results


def print_summary(processed_data):
    """Print formatted summary of processed data."""
    print("--- Student Summary ---")
    for item in processed_data:
        print(f"Name: {item['name']} | Average: {item['average']} | Status: {item['status']}")


if __name__ == "__main__":
    # Using the refactored data structure directly
    out = process_students(data)
    print_summary(out)
